from sqlalchemy import select, update
from app.db import Session
from app.orders.models import Order


def get(order_id: int) -> Order | None:
    with Session() as s:
        return s.get(Order, order_id)


def list_for_customer(customer_id: int, limit: int = 50) -> list[Order]:
    with Session() as s:
        return list(s.scalars(select(Order).where(Order.customer_id == customer_id).order_by(Order.created_at.desc()).limit(limit)))


def cancel(order_id: int) -> None:
    with Session() as s:
        s.execute(update(Order).where(Order.id == order_id).values(status="cancelled"))
        s.commit()
